/**
 * Shared board fixtures (story 4, tasks 3/6/9).
 *
 * `buildRetroBoard` generates the 25-note retro board: mixed colours,
 * multi-line text, overlapping positions and a re-ordered stack (z) so the
 * fixture exercises text, colour, position and stack order. `buildLargeBoard`
 * generates the PERSIST_TESTED_NOTES-note board with realistic phrase
 * lengths (10–300 characters) arranged in clusters.
 *
 * Both build note-by-note in a single transaction per note, so they return
 * one Yjs update per note (plus one per later re-stack) and a single update
 * holding the whole board for fast e2e seeding. Note ids and timestamps are
 * generated by the shared board-model API; snapshot comparisons are between
 * the original doc and a doc reloaded from the same bytes, so they stay
 * exact. Phrase lengths use a seeded PRNG so the encoded size of the large
 * board is stable run to run.
 */
import * as Y from 'yjs';
import { GRID_SPACING_WORLD, STICKY_COLORS, PERSIST_TESTED_NOTES, type StickyColor } from '../../src/shared/config';
import {
  bringToFront,
  createSticky,
  getStickyText,
  snapshot,
  type ObjectSnapshot,
} from '../../src/shared/board-model';

export interface FixtureResult {
  doc: Y.Doc;
  /** One Yjs update per note (and per re-stack), in order. */
  perNoteUpdates: Uint8Array[];
  /** A single update holding the whole board (fast seeding). */
  fullUpdate: Uint8Array;
  notes: readonly ObjectSnapshot[];
  ids: string[];
}

/** Deterministic PRNG (mulberry32) for stable phrase lengths. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const WORDS = [
  'ship', 'the', 'prototype', 'before', 'friday', 'review', 'the', 'roadmap', 'with', 'the',
  'team', 'cut', 'scope', 'for', 'the', 'launch', 'spike', 'on', 'persistence', 'draft',
  'the', 'release', 'notes', 'sync', 'with', 'design', 'about', 'the', 'camera', 'fix',
  'measure', 'note', 'auto', 'fit', 'behaviour', 'profile', 'the', 'compaction', 'thresholds',
  'against', 'real', 'board', 'sizes', 'write', 'down', 'the', 'rollback', 'plan', 'ask',
  'about', 'the', 'hibernation', 'budget', 'retest', 'the', 'quarantine', 'path', 'after',
  'every', 'storage', 'change', 'keep', 'the', 'load', 'under', 'three', 'seconds',
];

/** A realistic English phrase between 10 and 300 characters. */
function phrase(rand: () => number): string {
  const targetWords = 3 + Math.floor(rand() * 12);
  const words: string[] = [];
  for (let i = 0; i < targetWords; i++) {
    words.push(WORDS[Math.floor(rand() * WORDS.length)]);
  }
  let text = words.join(' ');
  if (rand() < 0.35) {
    const extra = Math.floor(rand() * 20) + 8;
    const more: string[] = [];
    for (let i = 0; i < extra; i++) more.push(WORDS[Math.floor(rand() * WORDS.length)]);
    text = `${text}. Follow up: ${more.join(' ')}`;
    if (text.length > 300) text = text.slice(0, 300);
  }
  return text.length < 10 ? `${text} today` : text;
}

function buildBoard(count: number, place: (i: number) => { x: number; y: number }, rand: () => number): FixtureResult {
  const doc = new Y.Doc();
  const perNoteUpdates: Uint8Array[] = [];
  const ids: string[] = [];
  const colors = Object.keys(STICKY_COLORS) as StickyColor[];

  const handler = (update: Uint8Array) => {
    perNoteUpdates.push(update);
  };

  for (let i = 0; i < count; i++) {
    {
      const at = place(i);
      const text =
        i % 3 === 0
          ? `Note ${i + 1} headline\nline 2 of ${i + 1}\nline 3 of ${i + 1}`
          : phrase(rand);
      // Each note is created on its own scratch doc (its own Yjs client),
      // mirroring a real multi-user board. Consequence: every note update
      // is independently applicable — quarantining one log row cannot
      // cascade into other notes' items (with a single shared client, Yjs
      // links map keys in creation order and a missing row silently drops
      // every later note of that client).
      const note = new Y.Doc();
      note.transact(() => {
        const id = createSticky(note, at, colors[i % colors.length]);
        ids.push(id);
        getStickyText(note, id)?.insert(0, text);
        // each scratch doc only sees its own note, so nextZ would give
        // every note z=1; assign the creation-order z explicitly so the
        // re-stack phase below has a real stack to reorder
        (note.getMap('objects').get(id) as Y.Map<unknown> | undefined)?.set('z', i + 1);
      }, 'fixture');
      // push explicitly (not via a doc listener): applyUpdate below would
      // also emit an 'update' event on `doc`, doubling the entry
      const update = Y.encodeStateAsUpdate(note);
      perNoteUpdates.push(update);
      Y.applyUpdate(doc, update, 'fixture');
    }
  }
  // Re-order the stack: every 4th earlier note moves to the front, so the
  // final z order differs from creation order. Listener on for this phase
  // only, so each re-stack is exactly one update.
  doc.on('update', handler);
  for (let i = 3; i < count - 1; i += 4) {
    doc.transact(() => {
      bringToFront(doc, ids[i]);
    }, 'fixture');
  }
  doc.off('update', handler);

  return {
    doc,
    perNoteUpdates,
    fullUpdate: Y.encodeStateAsUpdate(doc),
    notes: snapshot(doc),
    ids,
  };
}

/** The 25-note retro board: mixed colours, multi-line text, overlap, re-stacked z. */
export function buildRetroBoard(): FixtureResult {
  const rand = mulberry32(0x5eed);
  return buildBoard(
    25,
    (i) => {
      const col = i % 5;
      const row = Math.floor(i / 5);
      // 0.9 x spacing so neighbouring notes overlap in world space.
      return { x: col * GRID_SPACING_WORLD * 0.9, y: row * GRID_SPACING_WORLD * 0.9 };
    },
    rand,
  );
}

/**
 * The large board: `count` notes (default PERSIST_TESTED_NOTES) in 10x5
 * clusters; clusters sit far apart in world space and overlap only inside
 * a cluster.
 */
export function buildLargeBoard(count: number = PERSIST_TESTED_NOTES): FixtureResult {
  const rand = mulberry32(0xc0ffee);
  const NOTES_PER_CLUSTER = 50;
  const CLUSTER_COLS = 10;
  const CLUSTER_SPACING = GRID_SPACING_WORLD * 16;
  const IN_CLUSTER = GRID_SPACING_WORLD * 0.9;
  return buildBoard(
    count,
    (i) => {
      const cluster = Math.floor(i / NOTES_PER_CLUSTER);
      const inCluster = i % NOTES_PER_CLUSTER;
      const clusterCol = cluster % CLUSTER_COLS;
      const clusterRow = Math.floor(cluster / CLUSTER_COLS);
      return {
        x: clusterCol * CLUSTER_SPACING + (inCluster % 10) * IN_CLUSTER,
        y: clusterRow * CLUSTER_SPACING + Math.floor(inCluster / 10) * IN_CLUSTER,
      };
    },
    rand,
  );
}

/** Damage fixtures for TC-09 / TC-10. */

/** The last 10 bytes dropped — Yjs can no longer decode it. */
export function truncatedUpdate(update: Uint8Array): Uint8Array {
  return update.slice(0, Math.max(0, update.length - 10));
}

/** Same length, different (random) bytes. */
export function randomBytesSameLength(update: Uint8Array): Uint8Array {
  const out = new Uint8Array(update.length);
  for (let i = 0; i < update.length; i++) out[i] = Math.floor(Math.random() * 256);
  return out;
}
